bash: # Test the full P&L and gas calculation
TODAY="2026-02-10"
DAILY_PROFIT=$(grep "^${TODAY}" logs/transactions.log 2>/dev/null | \
  grep -E "status=SUCCESS" | \
  awk -F'|' '{
    gsub(/profit_usdc=/, "", $8);
    gsub(/ gas_pol=/, "", $8);
    gsub(/ \|/, "", $8);
    sum += $8
  } END {printf "%.4f", sum+0}')
echo "DAILY_PROFIT: $DAILY_PROFIT"

TOTAL_GAS=$(grep "^${TODAY}" logs/transactions.log 2>/dev/null | \
  awk -F'|' '{
    gsub(/gas_pol=/, "", $9);
    gsub(/ profit_usdc=/, "", $9);
    gsub(/ \|/, "", $9);
    sum += $9
  } END {printf "%.6f", sum+0}')
echo "TOTAL_GAS: $TOTAL_GAS"

# Test the bc comparison (which should not fail now)
echo "Testing bc comparison..."
if (( $(echo "$DAILY_PROFIT >= 25" | bc -l) )); then
  echo "P&L target reached"
else
  echo "P&L below target"
fi
